### form的一些使用注意点

react-hook-form这个仓库在使用的时候会遇到父子form嵌套导致子form提交时候也触发父级form的提交。

可以通过如下方式解决。

给form的表单提交设置成如下函数。

```typescript
const onSuccess = async (values: z.infer<typeof userInfoFormSchema>) => {
	console.log(values)
	toast.success('更新成功');
};

const onError = (errors: any) => {
	console.log(errors);
	toast.error('表单校验失败');
};

const onSubmit = async (event: React.FormEvent<HTMLFormElement>) => {
  // this part is for stopping parent forms to trigger their submit
  if (event) {
    // sometimes not true, e.g. React Native
    if (typeof event.preventDefault === 'function') {
      event.preventDefault();
    }
    if (typeof event.stopPropagation === 'function') {
      // prevent any outer forms from receiving the event too
      event.stopPropagation();
    }
  }

  return form.handleSubmit(onSuccess, onError)(event);
};

const formSchema = z.object({
	...
});

const form = useForm<z.infer<typeof formSchema>>({
	resolver: zodResolver(userInfoFormSchema),
	defaultValues: {
		...
	},
});

<Form {...form}>
	<form onSubmit={onSubmit} className='space-y-5'>
	...
	</form>
</Form>
```

## 操作步骤

### 相关数据

前往[https://developer.apple.com/account#MembershipDetailsCard](https://developer.apple.com/account#MembershipDetailsCard)页面获取自己的teamId

前往[https://developer.apple.com/account/resources/authkeys/list](https://developer.apple.com/account/resources/authkeys/list)生成新的key，获取其keyId并且将其文件下载。

### python的范本

```python
import httpx
import time
import uuid
import json
import jwt
import os

current_dir = os.path.dirname(__file__)

teamId = <your teamId>
keyId = <your keyId>

payload = {
    "iss": teamId,
    "iat": int(time.time()),
}

headers = {
    "alg" : "ES256",
    "kid" : keyId
}

# Apple Developer下载的p8文件
with open(os.path.join(current_dir, <authkeyfilename>), 'r') as f:
    privateKey = f.read()

token = jwt.encode(payload=payload, algorithm='ES256', headers=headers, key=privateKey)

headers = {
    "authorization": "bearer " + token,
    "apns-topic": "com.qingyun.Receiver",
    "apns-id": str(uuid.uuid4())
}

deviceToken = <your device token>

url = 'https://api.sandbox.push.apple.com/3/device/{}'.format(deviceToken)

def send_ios_notify(title, subtitle, body):
    data = {
        "aps" : {
            "alert" : {
                "title" : title,
                "subtitle" : subtitle,
                "body" : body
            },
            "sound": {
                "name": "default"
            },
        },
        "content-available": 1,
        "navigateToPage": "12345"
    }
    with httpx.Client(http2=True) as client:  # 使用上下文管理器
        try:
            res = client.post(url=url, headers=headers, json=data)
            print("推送成功:", res)
        except Exception as e:
            print("推送失败:", e)

if __name__ == "__main__":
    send_ios_notify("title", "subtitle", "body")
```

## 注意点

### 结构

apns-topic需要符合你的apple bundle identifier。

"content-available": 1 是用来让通知能够app在后台时点击通知能被应用处理

"navigateToPage": "12345"是额外自定义字段

### 应用在后台时候点击通知打开指定页面

```swift
//
//  AppDelegate.swift
//  Receiver
//
//  Created by Kinda on 2024/12/7.
//

import SwiftUI
import AuthenticationServices

// 扩展Data，将Data编码转成正常字符串
extension Data {
    var hexString: String {
        return map { String(format: "%02.2hhx", arguments: [$0]) }.joined()
    }
}

private func registerForRemoteNotifications() {
    UNUserNotificationCenter.current().requestAuthorization(options: [.alert, .badge, .sound]) { granted, error in
        if granted {
            DispatchQueue.main.async {
                UIApplication.shared.registerForRemoteNotifications()
            }
        } else {
            print("Notification permission not granted: \(String(describing: error))")
        }
    }
}

class AppDelegate: NSObject, UIApplicationDelegate, UNUserNotificationCenterDelegate {
    var window: UIWindow?

    func application(_ application: UIApplication,
                     didFinishLaunchingWithOptions launchOptions: [UIApplication.LaunchOptionsKey: Any]?) -> Bool {
        registerForRemoteNotifications()
        UNUserNotificationCenter.current().delegate = self
        return true
    }

    func application(_ application: UIApplication, didRegisterForRemoteNotificationsWithDeviceToken deviceToken: Data) {
        // 如果注册成功，那么会调用此处函数
        // 存储到 UserDefaults
        UserDefaults.standard.set(deviceToken.hexString, forKey: "deviceToken")
        print("deviceToken:", deviceToken.hexString)
    }

    func application(_ application: UIApplication, didFailToRegisterForRemoteNotificationsWithError error: Error) {
        print("Failed to register for remote notifications: \(error)")
    }

    // 前台接收到通知时
    func application(_ application: UIApplication, didReceiveRemoteNotification notification: [AnyHashable : Any], fetchCompletionHandler completionHandler: @escaping (UIBackgroundFetchResult) -> Void
    ) {
        NotificationCenter.default.post(name: .alert, object: notification)
        completionHandler(.newData)
    }

    // 点击通知打开应用时处理
    func userNotificationCenter(_ center: UNUserNotificationCenter,
                didReceive response: UNNotificationResponse,
                withCompletionHandler completionHandler:
                                @escaping () -> Void) {
        NotificationCenter.default.post(name: .navigateToPage, object: response.notification.request.content.userInfo, userInfo: response.notification.request.content.userInfo)
        completionHandler()
    }
}
```

其中

```swift
func application(_ application: UIApplication,
                   didFinishLaunchingWithOptions launchOptions: [UIApplication.LaunchOptionsKey: Any]?) -> Bool {
      registerForRemoteNotifications()
      UNUserNotificationCenter.current().delegate = self
      return true
  }
```

这段代码很重要，如果你发现你的userNotificationCenter不生效的话，检查一下是否执行了UNUserNotificationCenter.current().delegate = self，也就是是否将本函数介入UNUserNotificationCenter的生命周期（此话只是我的一种粗糙理解，简单地讲就是是否让这个函数生效，别的delegate类型也是如此，一定要设置为self）。

### Q1: 如果遇到在别的地方需要修改swiftui界面时，但又无法直接操作页面内的数据时，该怎么办呢？

#### 方法一：

**使用 @Published 和 ObservableObject**

通过 ObservableObject 和 @Published 将状态管理抽离到一个外部的共享数据模型中，然后通过 @EnvironmentObject 或 @StateObject 将数据绑定到页面。

**示例代码**

1. 定义状态管理类

```swift
import SwiftUI
import Combine

class SharedData: ObservableObject {
    @Published var message: String = "Hello, World!"
    @Published var count: Int = 0
}
```

2. 在视图中使用 @StateObject 或 @EnvironmentObject

```swift
struct ContentView: View {
    @StateObject var sharedData = SharedData() // 如果是全局共享数据，可以用 @EnvironmentObject

    var body: some View {
        VStack {
            Text(sharedData.message)
                .font(.title)

            Button("Increment Count") {
                sharedData.count += 1
            }

            Text("Count: \(sharedData.count)")
        }
        .onReceive(sharedData.$message) { newMessage in
            print("Message changed to: \(newMessage)")
        }
    }
}
```

3. 在其他地方更新数据

```swift
let sharedData = SharedData()
sharedData.message = "New Message"
sharedData.count = 42
```

当 sharedData.message 或 sharedData.count 被修改时，ContentView 会自动更新。

#### 方法二

使用NotificationCenter.default.post，这个方法基本无敌，可以在任何地方使用，不局限于swiftui页面。

**示例代码**

1. 定义通知的名称

```swift
extension Notification.Name {
    static let navigateToPage = Notification.Name("navigateToPage")
}
```

2. 在某处发送通知

```swift
let userInfo: [String: Any] = ["targetPage": "DetailPage", "data": "Example Data"]
NotificationCenter.default.post(name: .navigateToPage, object: nil, userInfo: userInfo)
```

3. 在 SwiftUI 页面接收通知

- 通过onReceive接受

```swift
import SwiftUI

struct ContentView: View {
    @State private var shouldNavigate: Bool = false
    @State private var navigationData: String = ""

    var body: some View {
        NavigationStack {
            VStack {
                Text("Home Page")
                NavigationLink(destination: DetailView(data: navigationData), isActive: $shouldNavigate) {
                    EmptyView()
                }
            }
            .onReceive(NotificationCenter.default.publisher(for: .navigateToPage)) { notification in
                if let userInfo = notification.userInfo,
                   let targetPage = userInfo["targetPage"] as? String,
                   let data = userInfo["data"] as? String,
                   targetPage == "DetailPage" {
                    navigationData = data
                    shouldNavigate = true
                }
            }
        }
    }
}

struct DetailView: View {
    let data: String

    var body: some View {
        Text("Detail Page with data: \(data)")
    }
}
```

- 通过.sink自己控制监听

> [!TIP]
> 注意这种方式需要自己取消监听

```swift
struct ContentView: View {
	@State private var notificationCancellable: AnyCancellable?

	...

	notificationCancellable = NotificationCenter.default
	            .publisher(for: .navigateToPage)
	            .sink { handleNotification($0) }

	func handleNotification(_ notification: Notification) {
			if let userInfo = notification.userInfo, let object = notification.object {
			    // 在这里执行你的逻辑
			    ...
	    }
	}

	var body: some View {
	        ZStack {
			        ...
	        }
	        .onDisappear {
				        // 取消监听
		            notificationCancellable?.cancel()
	        }
	    }
}
```

